          type: "paragraph",
          styleId: "Heading" + level,
          name: "heading " + level,
          basedOn: "Normal",
          next: "Normal",
          pPr: { spacing: { before: 240, after: 80 } },
          rPr: { bold: true, size: HEADING_SIZES[level - 1] }
